import React from 'react';

const Navbar = () => {
  return (
    <header className="fixed inset-x-0 top-0 z-50 bg-white/90 backdrop-blur-md border-b border-slate-200 shadow-sm">
      <div className="max-w-7xl mx-auto px-6 py-4 flex items-center justify-between">
        <div className="flex items-center gap-3">
          <div className="w-10 h-10 rounded-lg bg-gradient-to-r from-indigo-600 to-fuchsia-500 text-white grid place-items-center font-bold">U</div>
          <div>
            <h1 className="text-xl font-black text-slate-900">MediCampus</h1>
            <p className="text-xs text-slate-500">Healthcare System</p>
          </div>
        </div>

        <nav className="hidden md:flex items-center gap-6 text-slate-700 font-medium">
          <a href="#" className="hover:text-indigo-600 transition">Home</a>
          <a href="#features" className="hover:text-indigo-600 transition">Features</a>
          <a href="#dashboard" className="hover:text-indigo-600 transition">Dashboard</a>
          <a href="#contact" className="hover:text-indigo-600 transition">Contact</a>
          <a href="#" className="px-4 py-2 bg-indigo-600 text-white rounded-lg shadow-md hover:bg-indigo-500 transition">Book Appointment</a>
        </nav>

        <button className="md:hidden bg-indigo-600 text-white px-4 py-2 rounded-lg hover:bg-indigo-500 transition">Menu</button>
      </div>
    </header>
  );
};

export default Navbar;
